INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63612692', 63612692, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Asisten   Koordinasi Teknis Industri  Hijau', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 93600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Termin 1 tanggal 2 Februari : Dokumen Analisis Kondisi Terkini Perkembangan Industri Hijau di Indonesia 2. Termin 2 tanggal 2 Maret : Dokumen Analisis Ekonomi Sirkular Sektor Industri Tertentu di Indonesia 3. Termin 3 tanggal 1 April : Dokumen Analisis Daya Saing Ekonomi Sirkular Indonesia 4. Termin 4 tanggal 4 Mei : Dokumen Analisis Awal Kebijakan, Regulasi, dan Instrumen Pendukung Industri Hijau di Indonesia. 5. Termin 5 tanggal 1 Juni : Dokumen Analisis Kendala dan Tantangan Implementasi Industri Hijau 6. Termin 6 tanggal 1 Juli : Dokumen Analisis Pelaksanaan Industri Hijau Semester I 2026 7. Termin 7 tanggal 3 Agustus : Dokumen Analisis Best Practices Penerapan Industri Hijau 8. Termin 8 tanggal 1 September : Dokumen Analisis Peluang Peningkatan Kinerja Industri Hijau 9. Termin 9 tanggal 1 Oktober : Dokumen Analisis Penerapan Dekarbonisasi Industri 10. Termin 10 tanggal 2 November : Dokumen Analisis Best Practices Penerapan Dekarbonisasi Ind', 'Dukungan penyiapan bahan teknis non-kebijakan yang diperlukan dalam pelaksanaan kegiatan ekonomi sirkular dan dekarbonisasi industri, termasuk pengumpulan, pengolahan, dan perapihan bahan pendukung sesuai arahan ASN penanggung jawab. 2. Dukungan fasilitasi kegiatan dan pertemuan teknis, meliputi persiapan kegiatan, pengelolaan undangan, daftar hadir, notulensi, serta pendokumentasian kegiatan secara tertib dan sistematis. 3. Pengelolaan dan pemutakhiran informasi pendukung pemangku kepentingan yang relevan dengan kegiatan industri hijau, termasuk kementerian/lembaga teknis, pemerintah daerah, dunia usaha, asosiasi industri, serta mitra pembangunan, sebagai bahan dukungan koordinasi internal Direktorat. 4. Dukungan pengelolaan dokumentasi dan arsip kegiatan, termasuk pengelompokan, penyimpanan, dan penelusuran dokumen teknis operasional yang dihasilkan dari pelaksanaan kegiatan. 5. Dukungan komunikasi teknis-operasional dengan pemangku kepentingan terkait industri hijau dalam rangka fasilitasi kegiatan Direktorat, sesuai arahan dan penugasan ASN penanggung jawab. 6. Pelaksanaan tugas pendukung lainnya yang relevan dengan kegiatan ekonomi sirkular dan dekarbonisasi industri sepanjang bersifat teknis operasional serta tidak mencakup kewenangan strategis, pengambilan keputusan, maupun pelaksanaan fungsi Aparatur Sipil Negara (ASN).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1082620);
